class RefineProposalsResponse1(AdcpResponse, ProtocolEnvelope):
    model_config = ConfigDict(
        extra='allow',
    )
    results: Annotated[
        list[Results8],
        Field(
            description="Results in the request's refinements[] order; position carries no ranking. If any result is finalized, every result MUST be finalized; under inventory_hold semantics a finalize batch either creates every requested hold or none, and under terms_only semantics (get_adcp_capabilities media_buy.proposal_refinement.hold_semantics, or a draft hold_policy with available false) it commits every requested proposal's terms or none, with no inventory hold placed for those entries. An extend_hold batch either extends every requested hold or none. Every returned proposal carries parent_proposal_id equal to the result's source_proposal_id, making negotiation lineage reconstructible from the proposals alone.",
            min_length=1,
        ),
    ]
    products: Annotated[
        list[canonical_product.CanonicalProduct],
        Field(
            description="Canonical products needed to evaluate the resulting terms. For revised or partial results whose effective criteria contain property or collection lists, each affected product MUST carry fresh list_applications receipts from the revision's product reevaluation. Finalization changes no terms and MAY repeat the receipts already bound to the source proposal rather than reevaluating them."
        ),
    ]
    collections: Annotated[
        list[response_collection.ResponseCollection] | None,
        Field(
            description="Experimental (media_buy.collection_cards). Full collection objects for collections referenced by the collections selectors of the returned products. Sellers MUST NOT return this array unless the request set include_collections to true; when it is set, sellers SHOULD include every referenced collection and MUST NOT include one that no returned product references. At most one entry per (publisher_domain, collection_id). If a key appears more than once, that collection is unresolvable from this response; buyers fall back to the publisher's adagents.json, as they do for an omitted collection, and ignore entries that no returned product references. These are convenience copies, never authorization evidence: a copy wins over adagents.json only on images, sample_content, url, description, season, cadence and distribution[].followers (see core/response-collection.json). Present only alongside products.",
            min_length=1,
        ),
        NoExplicitNull,
    ] = None
    expected_confirmation_at: Annotated[
        WireDatetime | None,
        Field(
            description='Optional estimate, on a submitted response to a finalize-only or extend_hold-only request, of when the seller expects to resolve the finalize or extension, for example when a creator, host or talent must agree before the hold or its extension. Same semantics as on `create_media_buy`: an estimate, not a commitment or expiry; buyers SHOULD schedule a status check for it and MUST NOT treat a passed timestamp as failure. Sellers SHOULD NOT send it on revise requests.'
        ),
        NoExplicitNull,
    ] = None
    errors: Annotated[list[error.Error] | None, NoExplicitNull] = None
    context: Annotated[context_1.ContextObject | None, NoExplicitNull] = None
    ext: Annotated[ext_1.ExtensionObject | None, NoExplicitNull] = None
    status: Annotated[Literal['completed'], OmitUnsetDefault] = 'completed'


